"""Executable WP73 publication successor. ROOT reviewed exact quietpoint. No workflow commands.

Only a separately reviewed/frozen successor plus actual ROOT quietpoint may publish.
Actual803 baseline is bound; exact ROOT-reviewed publication marker is armed.
Only ROOT review plus a separately frozen executable successor can advance.
"""
from pathlib import Path
import hashlib,json,os,stat,subprocess,gzip,sys
HERE=Path(__file__).parent
REPO=Path('/home/lynn/projects/wordling')
MANIFEST=HERE/'promotion-manifest.json'
FROZEN_MANIFEST_SHA256='916a13c4fbbc6f9eba59e95899a17003fd3879f8ed032df277199790c84857ae'
EXPECTED_HEAD='803d1a4010f2aab83bba8522a87d5c38fdfbbb6e'
EXECUTION_ARMED=True

def sha(raw):return hashlib.sha256(raw).hexdigest()
def regular(path):
    if path.is_symlink() or not stat.S_ISREG(path.lstat().st_mode):raise RuntimeError('nonregular '+str(path))
    return path.read_bytes()
def relative(value):
    p=Path(value)
    if p.is_absolute() or '..' in p.parts or '\x00' in value:raise RuntimeError('bad relative path')
    return p

def assert_parents(path,stop):
    for q in path.parents:
        if q==stop:break
        if os.path.lexists(q) and (q.is_symlink() or not q.is_dir()):raise RuntimeError('unsafe parent '+str(q))

def preflight():
    if EXPECTED_HEAD is None:raise RuntimeError('DISABLED unbound candidate: ROOT post72approval quietpoint binding required')
    raw=regular(MANIFEST)
    if sha(raw)!=FROZEN_MANIFEST_SHA256:raise RuntimeError('manifest drift')
    m=json.loads(raw)
    if m['repo']!=str(REPO) or m['base']!=EXPECTED_HEAD or m['guard']!='current-guard.json.gz' or m['branch']!='feat/wp51-parity':raise RuntimeError('wrong fixed ROOT post72approval binding')
    for args,expected in [(['rev-parse','HEAD'],m['base']+'\n'),(['branch','--show-current'],m['branch']+'\n'),(['status','--porcelain=v1','--untracked-files=all'],'')]:
        if subprocess.check_output(['git',*args],cwd=REPO).decode()!=expected:raise RuntimeError('git guard '+str(args))
    own=json.loads(regular(HERE/'seals.json'))
    own_expected={r['path'] for r in own['members']}|{'seals.json'}
    own_actual={str(q.relative_to(HERE)) for q in HERE.rglob('*') if q.is_file()}
    if own_actual!=own_expected:raise RuntimeError('preparation closed set drift')
    for r in own['members']:
        b=regular(HERE/relative(r['path']))
        if len(b)!=r['bytes'] or sha(b)!=r['sha256'] or oct(stat.S_IMODE((HERE/relative(r['path'])).stat().st_mode))!=r['mode']:raise RuntimeError('preparation payload drift')
    guard=json.loads(gzip.decompress(regular(HERE/m['guard'])))
    actual={str(q.relative_to(REPO)) for q in (REPO/'kitty-specs/wp51-parity-01M64CVY').rglob('*') if q.is_file()}|{r['path'] for r in guard['files'] if not r['path'].startswith('kitty-specs/wp51-parity-01M64CVY/')}
    if actual!={r['path'] for r in guard['files']}:raise RuntimeError('complete selected baseline pathSET drift')
    for r in guard['files']:
        q=REPO/relative(r['path']);assert_parents(q,REPO);b=regular(q)
        if len(b)!=r['bytes'] or sha(b)!=r['sha256'] or oct(stat.S_IMODE(q.stat().st_mode))!=r['working_mode']:raise RuntimeError('baseline drift '+r['path'])
    for rel in guard['manifests_absent']:
        if os.path.lexists(REPO/relative(rel)):raise RuntimeError('unexpected manifest')
    publication=json.loads(regular(HERE/m['payload_map']));rows=publication['payloads']
    if len(rows)!=89 or len({r['target'] for r in rows})!=89:raise RuntimeError('payload cardinality/collision')
    grouped={}
    for r in rows:
        src=Path(r['source_root']);rel=relative(r['source_relative']);q=src/rel
        if str(q)!=r['source']:raise RuntimeError('source mapping mismatch')
        assert_parents(q,src);b=regular(q)
        if len(b)!=r['bytes'] or sha(b)!=r['sha256'] or oct(stat.S_IMODE(q.stat().st_mode))!=r['source_mode']:raise RuntimeError('source payload drift')
        inert=str(rel).endswith(('.py','.go'));dest=str(rel)+('.txt' if inert else '')
        if r['target_relative']!=dest or r['target']!=r['target_root']+'/'+dest or r['mode']!=format(int(r['source_mode'],8),'04o') or int(r['source_mode'],8) not in (0o644,0o664):raise RuntimeError('adaptation mismatch')
        if r['target_root'] not in m['new_roots'][:2]:raise RuntimeError('foreign root')
        grouped.setdefault(src,set()).add(str(rel))
    for src,expected in grouped.items():
        if any(q.is_symlink() for q in src.rglob('*')):raise RuntimeError('source symlink')
        if {str(q.relative_to(src)) for q in src.rglob('*') if q.is_file()}!=expected:raise RuntimeError('source closed set drift')
    for rel in m['new_roots']+[m['task_target']]+[r['target']+'.WP73-promotion.tmp' for r in m['summary_replacements']]:
        q=REPO/relative(rel);assert_parents(q,REPO)
        if os.path.lexists(q):raise RuntimeError('new target exists '+rel)
    for r in m['summary_replacements']:
        before=regular(REPO/relative(r['target']));after=regular(HERE/relative(r['source']));append=regular(HERE/relative(r['append_source']))
        if sha(before)!=r['before_sha256'] or sha(after)!=r['after_sha256'] or after!=before+append:raise RuntimeError('summary mismatch')
    for history in m['prior_preparations']:
        source=Path(history['source_root'])
        if sha(regular(source/'seals.json'))!=history['root_seal_sha256']:raise RuntimeError('prior preparation seal drift')
        expected={r['source_relative'] for r in history['members']}
        if any(q.is_symlink() for q in source.rglob('*')) or {str(q.relative_to(source)) for q in source.rglob('*') if q.is_file()}!=expected:raise RuntimeError('prior preparation closed set drift')
        for r in history['members']:
            q=source/relative(r['source_relative']);assert_parents(q,source);b=regular(q)
            if len(b)!=r['bytes'] or sha(b)!=r['sha256'] or oct(stat.S_IMODE(q.stat().st_mode))!=r['mode']:raise RuntimeError('prior preparation payload drift')
            target=history['target_prefix']+r['source_relative']+('.txt' if r['source_relative'].endswith(('.py','.go')) else '')
            if r['target_relative']!=target:raise RuntimeError('prior preparation adaptation drift')
    return m,rows

def create(rel,raw,mode=0o644):
    target=REPO/relative(rel);assert_parents(target,REPO);target.parent.mkdir(parents=True,exist_ok=True)
    fd=os.open(target,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW|os.O_CLOEXEC,mode)
    try:
        os.fchmod(fd,mode);view=memoryview(raw)
        while view:
            n=os.write(fd,view)
            if n<=0:raise RuntimeError('zero progress')
            view=view[n:]
        os.fsync(fd)
    finally:os.close(fd)
    if regular(target)!=raw:raise RuntimeError('readback mismatch')

def publication_seal(root):
    directory=REPO/relative(root);rows=[]
    for q in sorted(directory.rglob('*')):
        if q.is_file():
            b=regular(q);rows.append({'path':str(q.relative_to(directory)),'bytes':len(b),'sha256':sha(b),'mode':format(stat.S_IMODE(q.stat().st_mode),'04o')})
    create(root+'/publication-seal.json',(json.dumps({'meaning':'Transformed publication; excludes only THIS exact root publication-seal.json; all nested historical seals included.','members':rows},indent=2)+'\n').encode())

def publish():
    if not EXECUTION_ARMED:raise RuntimeError('DISABLED candidate: actual ROOT quietpoint and frozen successor required; no JSON/file grants')
    m,rows=preflight()
    # Trusted sole writer, not hostile filesystem atomic transaction. No workflow
    # command is executed here. On any partial failure STOP and retain it.
    origins={str(q.relative_to(HERE)):regular(q) for q in HERE.rglob('*') if q.is_file()}
    for root in m['new_roots']:os.mkdir(REPO/relative(root))
    for r in rows:create(r['target'],regular(Path(r['source'])),int(r['mode'],8))
    for root in m['new_roots'][:2]:
        subset=[r for r in rows if r['target_root']==root]
        create(root+'/publication-manifest.json',(json.dumps({'meaning':'All original payloads once; old seals mean ORIGINAL names only; this map and new publication-seal bind transformed destinations.','files':subset},indent=2)+'\n').encode())
        publication_seal(root)
    promotion=m['new_roots'][2];origin_map=[]
    for name,b in sorted(origins.items()):
        dest='prepared-origin/'+name+('.txt' if name.endswith(('.py','.go')) else '')
        create(promotion+'/'+dest,b);origin_map.append({'original_name':name,'target_relative':dest,'bytes':len(b),'sha256':sha(b),'mode':'0644'})
    for history in m['prior_preparations']:
        for r in history['members']:
            create(promotion+'/'+r['target_relative'],regular(Path(history['source_root'])/relative(r['source_relative'])),int(r['mode'],8))
    create(promotion+'/prior-preparation-manifest.json',(json.dumps(m['prior_preparations'],indent=2)+'\n').encode())
    create(promotion+'/prepared-origin-manifest.json',(json.dumps({'original_seal_scope':'Original preparation names only; use separate transformed publication seal.','files':origin_map},indent=2)+'\n').encode())
    for r in m['summary_replacements']:create(promotion+'/before/'+Path(r['target']).name,regular(REPO/relative(r['target'])))
    create(m['task_target'],regular(HERE/relative(m['task_source'])))
    for r in m['summary_replacements']:
        target=REPO/relative(r['target'])
        if sha(regular(target))!=r['before_sha256']:raise RuntimeError('late summary drift')
        temp=r['target']+'.WP73-promotion.tmp';create(temp,regular(HERE/relative(r['source'])))
        os.replace(REPO/relative(temp),target)
        fd=os.open(target.parent,os.O_RDONLY|os.O_DIRECTORY|os.O_CLOEXEC)
        try:os.fsync(fd)
        finally:os.close(fd)
    publication_seal(promotion)
    print(json.dumps({'published':True,'candidate_WP73_only':True,'next':'STOP. Inspect complete exact delta/readback, then separately authorized normal CLI gates. No claim/commit/push/accept/merge or original permission.'}))

if __name__=='__main__':
    if sys.argv[1:]==['--preflight']:
        manifest,rows=preflight()
        print(json.dumps({'readonly_preflight':True,'base':manifest['base'],'payloads':len(rows),'publication_armed':EXECUTION_ARMED,'canonical_writes':False}))
    elif sys.argv[1:]==['--publish','WP73-803d1a40-reviewed-publication-quietpoint']:
        publish()
    else:
        raise SystemExit('Only exact ROOT-granted publication marker or read-only preflight.')
